long long tak(long long x, long long y, long long z) {
    if (y < x)
        return tak(tak(x - 1, y, z), tak(y - 1, z, x), tak(z - 1, x, y));
    return y;
}

#include <assert.h>
#include "tak.c"

int main(void) {
    assert(tak(6, 4, 2) == 3);
    assert(tak(12, 8, 4) == 5);
    assert(tak(1, 2, 3) == 3);
    return 0;
}
